from functools import reduce

def total_length(words):
    return reduce(lambda acc, w: acc + len(w), words, 0)

print(total_length(['çay', 'simit']), total_length([]))

def ranking(students):
    return sorted(students, key=lambda s: (-s[1], s[0]))

print(ranking([('Ece', 80), ('Can', 95), ('Ada', 80)]))

from functools import reduce

def join_countries(countries):
    if len(countries) == 1:
        return countries[0] + ' is a north European country'
    head = reduce(lambda a, b: a + ', ' + b, countries[:-1])
    return head + ', and ' + countries[-1] + ' are north European countries'

def count_by_first_letter(countries):
    counts = {}
    for name in countries:
        letter = name[0].upper()
        counts[letter] = counts.get(letter, 0) + 1
    return {k: counts[k] for k in sorted(counts)}
